  /**/
  // (1) Thumbnail resolution.
  // Blogger hands out post thumbnails at /s72-c/ (72px) or /w72-h72-c/ (72x72).
  // On a phone the card thumb is 88 CSS px at devicePixelRatio 3, so it needs
  // ~264 real px - a 72px source looks like a blurry smudge. Request a 3:2 crop
  // at 480px instead, which is both sharp on a 3x phone and still small enough
  // to be cheap on desktop.
  // (2) In-article AdSense unit moves to just after the 3rd paragraph.
  // The unit is MOVED, never duplicated: rendering the same data-ad-slot twice
  // on one page is an AdSense policy violation. A spacer of the same height is
  // inserted first so the page does not grow, which keeps CLS near zero.
  (function () {
    var THUMB_RE = /\/(?:s\d+(?:-c)?|w\d+-h\d+(?:-c)?|w=\d+-h=\d+|s\d+x\d+)\//;
    var THUMB_OUT = '/w480-h320-c/';

    function fixThumbs(root) {
      var sel = '.mbtlist .iFeatured img, .blog-posts .Image.thumb img, ' +
                '.post-body .Image.thumb img';
      var nodes = (root || document).querySelectorAll(sel);
      for (var i = 0; i < nodes.length; i++) {
        var img = nodes[i];
        var src = img.getAttribute('src') || '';
        if (!src || src.indexOf(THUMB_OUT) > -1) continue;
        var next = src.replace(THUMB_RE, THUMB_OUT);
        if (next === src) continue;
        img.setAttribute('data-thumb-fallback', src);
        img.setAttribute('src', next);
        // If the resized variant 404s, fall back to whatever Blogger gave us.
        img.addEventListener('error', function () {
          var fb = this.getAttribute('data-thumb-fallback');
          if (fb && this.getAttribute('src') !== fb) {
            this.setAttribute('src', fb);
            this.removeAttribute('data-thumb-fallback');
          }
        });
      }
    }

    function moveAd() {
      var ad = document.querySelector('.post-ad');
      if (!ad || ad.getAttribute('data-moved') === '1') return;
      var body = document.querySelector('.post-body');
      if (!body) return;
      var paras = [].filter.call(body.children, function (el) {
        return el.tagName === 'P' && el.textContent.trim().length > 0;
      });
      if (paras.length < 3) return; // static pages / short posts: leave it alone

      var reserved = window.getComputedStyle(ad).minHeight || '280px';
      var host = document.createElement('div');
      host.className = 'post-ad-host';
      host.style.minHeight = reserved;
      body.insertBefore(host, paras[2].nextSibling);

      ad.parentNode.removeChild(ad);
      ad.removeAttribute('style');
      ad.style.margin = '0';
      ad.setAttribute('data-moved', '1');
      host.appendChild(ad);
    }

    function init() { fixThumbs(); moveAd(); }

    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', init);
    } else {
      init();
    }
    // Sidebar feed renders after document ready.
    window.addEventListener('load', fixThumbs);
  })();
