    function inject() {
      if (loaded) return;
      loaded = true;
      var s = document.createElement('script');
      s.async = true;
      s.src = 'https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-4050278743595276';
      s.crossOrigin = 'anonymous';
      var first = document.getElementsByTagName('script')[0];
      first.parentNode.insertBefore(s, first);
    }
    // AGENT.md §6 asks for scroll-based lazy loading rather than an
    // IntersectionObserver, so keep the scroll listener and add a load
    // fallback: without it, a reader who never scrolls never sees an ad.
    window.addEventListener('scroll', function () {
      var y = window.pageYOffset ||
              (document.documentElement && document.documentElement.scrollTop) ||
              (document.body && document.body.scrollTop) || 0;
      if (y > 0) inject();
    }, { passive: true });
    window.addEventListener('load', inject);
  })();
