  (function () {
    var MIN_HEADINGS = 4;
    var TOC_LEVELS = { H2: 0, H3: 1 };

    function slugify(text) {
      return text.toLowerCase()
        .replace(/[^\w\s-]/g, '')
        .trim()
        .replace(/\s+/g, '-')
        .replace(/-+/g, '-')
        .replace(/^-|-$/g, '') || 'section';
    }

    function buildToc() {
      var body = document.querySelector('.post-body');
      if (!body || body.querySelector('.post-toc')) return;

      var headings = body.querySelectorAll('h2, h3');
      if (headings.length < MIN_HEADINGS) return;

      var used = {};
      var entries = [];
      var anchors = [];

      for (var i = 0; i < headings.length; i++) {
        var h = headings[i];
        // A heading wrapped in a link or holding only an image has no plain text
        // to show in the contents list.
        var title = (h.textContent || '').trim();
        if (!title) continue;

        var id = h.id;
        if (!id) {
          var base = slugify(title);
          var n = used[base] = (used[base] || 0) + 1;
          id = n === 1 ? base : base + '-' + n;
          h.id = id;
        }
        entries.push({ level: TOC_LEVELS[h.tagName.toUpperCase()], title: title, id: id });
        anchors.push(id);
      }

      if (entries.length < MIN_HEADINGS) return;

      var nav = document.createElement('nav');
      nav.className = 'post-toc';
      nav.setAttribute('aria-label', 'Table of contents');

      var caption = document.createElement('p');
      caption.className = 'post-toc-title';
      caption.appendChild(document.createTextNode('Table of contents'));
      nav.appendChild(caption);

      var list = document.createElement('ol');
      for (var j = 0; j < entries.length; j++) {
        var li = document.createElement('li');
        if (entries[j].level === 1) li.className = 'toc-h3';
        var a = document.createElement('a');
        a.href = '#' + entries[j].id;
        a.appendChild(document.createTextNode(entries[j].title));
        li.appendChild(a);
        list.appendChild(li);
      }
      nav.appendChild(list);
      nav.setAttribute('data-ready', '1');

      var firstPara = null;
      var children = body.children;
      for (var k = 0; k < children.length; k++) {
        if (children[k].tagName === 'P' && (children[k].textContent || '').trim()) {
          firstPara = children[k];
          break;
        }
      }
      if (firstPara) firstPara.parentNode.insertBefore(nav, firstPara.nextSibling);
      else body.insertBefore(nav, body.firstChild);

      // A jump link pointing at an id nothing owns would silently do nothing,
      // which is how a reader ends up convinced a contents list is broken.
      document.addEventListener('click', function (ev) {
        var link = ev.target && ev.target.closest ? ev.target.closest('a[href^="#"]') : null;
        if (!link) return;
        var target = link.getAttribute('href').slice(1);
        if (!target || document.getElementById(target)) return;
        ev.preventDefault();
      });
    }

    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', buildToc);
    } else {
      buildToc();
    }
  })();
